# Construct inferred output: normalize each diagonal segment to median length 4,
# preserving its upper-right (largest-column) endpoint.
g=[[7]*16 for _ in range(16)]
segments = {
    5: [(0,7,4), (2,9,4)],
    8: [(4,11,4)],
    4: [(6,13,4), (8,15,4)],
}
for color, segs in segments.items():
    for r0,c0,n in segs:
        for d in range(n):
            g[r0+d][c0-d]=color
print(len(g), [len(row) for row in g])
print(g)
import json
print(json.dumps(g,separators=(',',':')))

